523	export function traced<A extends unknown[], R>(kind: 'WORKFLOW' | 'CHAIN' | 'AGENT' | 'TOOL' | 'GUARDRAIL', name: string, fn: (...a: A) => Promise<R>): (...a: A) => Promise<R>
