684	it('detects the pause in a generated clip');   // ffmpeg -f lavfi: 1 s sine, 0.8 s silence, 1 s sine -> one silence near 1.0–1.8
685	it('rotates to the next key on 429 and to the next model when all keys fail');   // fetchImpl stub
